theme.css:
/* theme: Shattered Momentum | A market-defining collapse — China's AI bubble burst — sets the tone: a sharp, dark, high-contrast page where a single red line of decline cuts through everything, from the header's broken grid to the stock cards' falling sparklines. */
/* layout: hero=split; political-news=timeline/stack; financial-news=stat/feature; entertainment-news=lede/masonry; music-releases=numbered/grid-2; stock-analysis=stat/grid-3; outlook=outline/stack */

.diary-page {
  --paper: #0e0e11;
  --paper-alt: #1a1a20;
  --ink: #e8e8ee;
  --ink-soft: #b3b3c2;
  --muted: #8a8a99;
  --accent: #ff3d2e;
  --accent-ink: #0e0e11;
  --rule: #2e2e3a;
  --font-display: var(--ff-instrument), Georgia, serif;
  --font-body: var(--ff-newsreader), Georgia, serif;
  --font-ui: var(--ff-inter), system-ui, sans-serif;
}

@media (prefers-color-scheme: light) {
  .diary-page {
    --paper: #0e0e11;
    --paper-alt: #1a1a20;
    --ink: #e8e8ee;
    --ink-soft: #b3b3c2;
    --muted: #8a8a99;
    --accent: #ff3d2e;
    --accent-ink: #0e0e11;
    --rule: #2e2e3a;
  }
}

/* Split header: fractured masthead, red streak cuts through */
.diary-page[data-hero="split"] .diary-hero {
  background: var(--paper);
  border-bottom: 2px solid var(--accent);
  position: relative;
}

.diary-page[data-hero="split"] .diary-hero::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: linear-gradient(135deg, var(--accent) 0%, transparent 45%, transparent 55%, var(--accent) 100%);
  opacity: 0.08;
  pointer-events: none;
}

.diary-page[data-hero="split"] .diary-hero-inner {
  padding-block: 2rem 3.5rem;
}

.diary-page[data-hero="split"] .diary-title {
  font-size: clamp(2.8rem, 8vw, 5.5rem);
  line-height: 0.95;
  text-transform: none;
  letter-spacing: -0.03em;
  max-width: none;
  color: var(--ink);
}

.diary-page[data-hero="split"] .diary-title::before {
  content: "";
  display: block;
  width: 4rem;
  height: 4px;
  background: var(--accent);
  margin-bottom: 0.75rem;
  border-radius: 2px;
}

.diary-page[data-hero="split"] .diary-title::after {
  content: "";
  display: block;
  width: 4rem;
  height: 4px;
  background: var(--accent);
  margin-top: 0.75rem;
  border-radius: 2px;
}

.diary-page[data-hero="split"] .diary-summary {
  max-width: 44rem;
  color: var(--ink-soft);
  font-size: 1.1rem;
  line-height: 1.6;
  border-left: 3px solid var(--accent);
  padding-left: 1.25rem;
  margin-top: 1.5rem;
}

.diary-page[data-hero="split"] .diary-theme-note {
  color: var(--muted);
}

.diary-page[data-hero="split"] .diary-theme-name {
  background: var(--accent);
  color: var(--accent-ink);
}

.diary-page[data-hero="split"] .diary-kicker {
  color: var(--accent);
}

.diary-page[data-hero="split"] .diary-crumbs a {
  color: var(--muted);
}

/* Contents: dark sidebar, red active mark */
.diary-page .diary-toc {
  background: var(--paper);
  border-bottom: 1px solid var(--rule);
}

.diary-page .diary-toc-link,
.diary-page .diary-toc-top {
  color: var(--muted);
}

.diary-page .diary-toc-link:hover,
.diary-page .diary-toc-top:hover,
.diary-page .diary-toc-link.is-active {
  color: var(--ink);
}

.diary-page .diary-toc-number {
  color: var(--accent);
}

@media (min-width: 1024px) {
  .diary-page .diary-toc-link.is-active {
    border-left-color: var(--accent);
    border-left-width: 3px;
  }

  .diary-page .diary-toc-label {
    color: var(--muted);
  }
}

/* Section heads: sharp red numbers and thin rules */
.diary-page .diary-section {
  border-top: 2px solid var(--rule);
}

.diary-page .diary-section:first-child {
  border-top: 0;
}

.diary-page .diary-section-number {
  color: var(--accent);
  font-size: 1rem;
}

.diary-page .diary-section-title {
  color: var(--ink);
  font-family: var(--font-display);
  font-size: clamp(2rem, 3.5vw, 3rem);
  letter-spacing: -0.02em;
}

.diary-page .diary-section-head::after {
  content: "";
  flex: 1;
  border-top: 1px solid var(--rule);
  align-self: center;
}

/* Political: timeline of a concession — dots mark the pivots */
.diary-page[data-section="political-news"] .diary-card--timeline .diary-card-inner {
  position: relative;
  padding-left: 2.25rem;
}

.diary-page[data-section="political-news"] .diary-card--timeline .diary-card-inner::before {
  content: "";
  position: absolute;
  left: 0.6rem;
  top: 0;
  bottom: -1.5rem;
  width: 2px;
  background: var(--rule);
}

.diary-page[data-section="political-news"] .diary-card--timeline:last-child .diary-card-inner::before {
  bottom: 0;
}

.diary-page[data-section="political-news"] .diary-card--timeline .diary-card-inner::after {
  content: "";
  position: absolute;
  left: 0;
  top: 0.45rem;
  width: 1.1rem;
  height: 1.1rem;
  border-radius: 50%;
  background: transparent;
  border: 3px solid var(--accent);
  box-shadow: 0 0 0 5px var(--paper);
}

.diary-page[data-section="political-news"] .diary-card-title {
  font-size: 1.5rem;
  font-family: var(--font-display);
  color: var(--ink);
}

.diary-page[data-section="political-news"] .diary-card-body {
  color: var(--ink-soft);
  font-size: 1.05rem;
  line-height: 1.7;
}

.diary-page[data-section="political-news"] .diary-card-thread {
  border-color: var(--accent);
  color: var(--accent);
}

.diary-page[data-section="political-news"] .diary-card-thread:hover {
  background: var(--accent);
  color: var(--accent-ink);
}

/* Financial: one huge stat — the $480B number dominates */
.diary-page[data-section="financial-news"] .diary-card--stat {
  background: var(--paper-alt);
  border: 2px solid var(--accent);
}

.diary-page[data-section="financial-news"] .diary-card--stat .diary-card-inner {
  padding: 2rem 2.5rem;
}

.diary-page[data-section="financial-news"] .diary-card-figure {
  font-size: clamp(3.5rem, 16cqi, 6rem);
  color: var(--accent);
  font-family: var(--font-display);
  font-weight: 700;
}

.diary-page[data-section="financial-news"] .diary-card-figure::before {
  content: "−";
  margin-right: 0.15em;
}

.diary-page[data-section="financial-news"] .diary-card-title {
  font-size: 2rem;
  font-family: var(--font-display);
  color: var(--ink);
}

.diary-page[data-section="financial-news"] .diary-card-body {
  color: var(--ink-soft);
  font-size: 1.1rem;
  line-height: 1.7;
}

.diary-page[data-section="financial-news"] .diary-stories--feature .diary-card:first-child .diary-card-inner {
  border: 0;
  box-shadow: 0 0 0 1px var(--rule);
}

/* Entertainment: lede cards, broken by the loss */
.diary-page[data-section="entertainment-news"] .diary-card--lede .diary-card-inner {
  padding: 1.5rem;
  border: 1px solid var(--rule);
  background: var(--paper-alt);
}

.diary-page[data-section="entertainment-news"] .diary-card--lede .diary-card-lede {
  font-size: 1.4rem;
  font-family: var(--font-display);
  color: var(--ink);
  border-left: 4px solid var(--accent);
  padding-left: 1.1rem;
}

.diary-page[data-section="entertainment-news"] .diary-card--lede .diary-card-title {
  font-size: 1.3rem;
  color: var(--ink);
  font-family: var(--font-display);
}

.diary-page[data-section="entertainment-news"] .diary-card--lede .diary-card-body {
  color: var(--ink-soft);
  font-size: 1rem;
  line-height: 1.65;
}

/* Music: numbered cards like tracklists */
.diary-page[data-section="music-releases"] .diary-card--numbered .diary-card-inner {
  padding: 1.25rem;
  background: var(--paper-alt);
  border: 1px solid var(--rule);
}

.diary-page[data-section="music-releases"] .diary-card--numbered .diary-card-index {
  color: var(--accent);
  font-size: 2.5rem;
  font-family: var(--font-display);
}

.diary-page[data-section="music-releases"] .diary-card--numbered .diary-card-title {
  font-size: 1.2rem;
  color: var(--ink);
  font-family: var(--font-display);
}

.diary-page[data-section="music-releases"] .diary-card--numbered .diary-card-body {
  color: var(--ink-soft);
  font-size: 0.95rem;
}

.diary-page[data-section="music-releases"] .diary-embed {
  border: 1px solid var(--rule);
  background: var(--paper-alt);
}

/* Stock: stat cards with red-falling figures */
.diary-page[data-section="stock-analysis"] .diary-card--stat .diary-card-inner {
  padding: 1rem 1.25rem;
  border-top: 4px solid var(--accent);
  background: var(--paper);
}

.diary-page[data-section="stock-analysis"] .diary-card-figure {
  color: var(--accent);
  font-family: var(--font-display);
  font-size: clamp(2rem, 10cqi, 3rem);
}

.diary-page[data-section="stock-analysis"] .diary-card-figure::before {
  content: "▼ ";
  font-size: 0.7em;
  margin-right: 0.2em;
}

.diary-page[data-section="stock-analysis"] .diary-card-title {
  color: var(--ink);
  font-family: var(--font-display);
  font-size: 1.25rem;
}

.diary-page[data-section="stock-analysis"] .diary-card-body {
  color: var(--ink-soft);
  font-size: 0.95rem;
  line-height: 1.6;
}

/* Markets wrap: dark panels, falling sparklines */
.diary-page .diary-markets {
  background: var(--paper-alt);
  border: 1px solid var(--rule);
}

.diary-page .diary-spark {
  background: var(--paper);
  border-color: var(--rule);
}

.diary-page .diary-spark.is-down .diary-spark-change {
  color: var(--accent);
}

.diary-page .diary-spark.is-up .diary-spark-change {
  color: var(--ink);
}

.diary-page .diary-spark .diary-spark-line {
  stroke: currentColor;
}

/* Outlook: outlined cards, quiet but tense */
.diary-page[data-section="outlook"] .diary-card--outline .diary-card-inner {
  padding: 1.5rem;
  border: 1px solid var(--rule);
  background: var(--paper);
}

.diary-page[data-section="outlook"] .diary-card--outline .diary-card-title {
  color: var(--ink);
  font-family: var(--font-display);
  font-size: 1.4rem;
}

.diary-page[data-section="outlook"] .diary-card--outline .diary-card-body {
  color: var(--ink-soft);
  font-size: 1.05rem;
  line-height: 1.7;
}

/* Body prose: red citation links, dark ink */
.diary-page .diary-prose {
  color: var(--ink-soft);
}

.diary-page .diary-prose strong {
  color: var(--ink);
}

.diary-page .diary-prose a {
  color: var(--accent);
  border-bottom: 1px solid var(--accent);
}

.diary-page .diary-prose a:hover {
  color: var(--ink);
}

.diary-page .diary-prose blockquote {
  border-left-color: var(--accent);
  color: var(--ink);
}

.diary-page .diary-prose ul > li::before {
  background: var(--accent);
}

.diary-page .diary-prose ol > li::marker {
  color: var(--accent);
}

/* Lede drop cap with red accent */
.diary-page .diary-section:first-child .diary-card--plain:first-child .diary-prose > p:first-of-type::first-letter {
  color: var(--accent);
}

/* Cards: dark theme friendly */
.diary-page .diary-card--outline .diary-card-inner,
.diary-page .diary-card--elevated .diary-card-inner,
.diary-page .diary-card--tile .diary-card-inner {
  border-color: var(--rule);
}

.diary-page .diary-card--elevated .diary-card-inner {
  box-shadow: 0 1px 2px rgb(0 0 0 / 0.5), 0 12px 32px -12px rgb(0 0 0 / 0.5);
}

.diary-page .diary-card--banner .diary-card-title {
  background: var(--accent);
  color: var(--accent-ink);
}

/* Sparkline polylines get the red/ink treatment */
.diary-page .diary-spark.is-down polyline {
  stroke: var(--accent);
}

.diary-page .diary-spark.is-up polyline {
  stroke: var(--ink);
}

/* Smooth entry: cards fade in subtly, once */
@media (prefers-reduced-motion: no-preference) {
  .diary-page .diary-card {
    animation: diary-card-fade 600ms ease-out;
  }

  @keyframes diary-card-fade {
    from {
      opacity: 0;
      transform: translateY(0.5rem);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }
}
